def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    exceeds_threshold = [value > 4000 for value in values]
    count = sum(exceeds_threshold)
    return {
        "value": count,
        "trace": {
            "exceeds_threshold_by_year": exceeds_threshold,
            "count": count,
            "output_meta": {"currency": None, "scale": None, "unit": "years"},
        },
    }
